//! Verify prose document count, one README per crate, competitor-name absence,
//! and register rules.

use std::fs;
use std::path::Path;
use walkdir::WalkDir;

const MAX_PROSE_DOCS: usize = 5;
const BANNED_COMPETITORS: &[&str] = &["Moondream", "MIRAGE_MEGAKERNEL", "PHOTON_2", "Mirage MPK"];
const BANNED_DOC_TOKENS: &[&str] = &[
    "CARGO_TARGET_DIR",
    "CARGO_BUILD_TARGET_DIR",
    "--target-dir",
    "/tmp/",
    "Co-Authored-By:",
    "Generated with Claude",
    "Generated by Claude",
    "\u{2014}",
    "\u{2013}",
];

/// Check tracked prose documentation count and content rules.
pub fn check(root: &Path) -> Result<(), Vec<String>> {
    let mut errors = Vec::new();
    let mut prose_docs = Vec::new();
    let mut crate_dirs = Vec::new();

    for entry in WalkDir::new(root)
        .into_iter()
        .filter_entry(|e| !crate::source_scan::is_pruned(e))
        .filter_map(Result::ok)
        .filter(|e| e.file_type().is_file())
    {
        let path = entry.path();
        let rel = path.strip_prefix(root).unwrap_or(path).to_string_lossy();
        let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("");
        let parent = path.parent().unwrap_or(root);
        if path.file_name().is_some_and(|name| name == "Cargo.toml") && parent != root {
            crate_dirs.push(parent.to_path_buf());
        }
        if matches!(ext, "md" | "adoc" | "rst") {
            // Transient in-flight deleted crate directories without Cargo.toml are ignored.
            if rel.starts_with("crates/") {
                let parts: Vec<&str> = rel.split('/').collect();
                if parts.len() >= 3
                    && !root
                        .join(parts[0])
                        .join(parts[1])
                        .join("Cargo.toml")
                        .is_file()
                {
                    continue;
                }
            }
            // A crate's own README is required, so it is outside the ceiling.
            let crate_readme = path.file_name().is_some_and(|name| name == "README.md")
                && parent != root
                && parent.join("Cargo.toml").is_file();
            if !crate_readme {
                prose_docs.push(rel.into_owned());
            }
            if let Ok(text) = fs::read_to_string(path) {
                for token in BANNED_DOC_TOKENS {
                    if text.contains(token) {
                        errors.push(format!(
                            "{}: contains banned token `{token}`",
                            path.display()
                        ));
                    }
                }
                for comp in BANNED_COMPETITORS {
                    if text.contains(comp) {
                        errors.push(format!(
                            "{}: names competitor `{comp}` in tracked doc",
                            path.display()
                        ));
                    }
                }
            }
        } else if matches!(ext, "rs" | "toml" | "yml") && !rel.starts_with("tools/xtask/") {
            if let Ok(text) = fs::read_to_string(path) {
                for comp in BANNED_COMPETITORS {
                    if text.contains(comp) {
                        errors.push(format!("{rel}: names competitor `{comp}` in tracked file"));
                    }
                }
            }
        }
    }

    crate_dirs.sort();
    for dir in &crate_dirs {
        if !dir.join("README.md").is_file() {
            let rel = dir.strip_prefix(root).unwrap_or(dir);
            errors.push(format!(
                "{}: crate has no README.md; add one stating its purpose and boundaries",
                rel.display()
            ));
        }
    }

    if prose_docs.len() > MAX_PROSE_DOCS {
        prose_docs.sort();
        errors.push(format!(
            "tracked prose docs ({}) exceed ceiling of {MAX_PROSE_DOCS}: {}",
            prose_docs.len(),
            prose_docs.join(", ")
        ));
    }

    if errors.is_empty() {
        Ok(())
    } else {
        Err(errors)
    }
}
